152-// --- the decode (DESIGN §4, "legacy spellings — written never, read forever") --
153-/ Labels are STORED DATA: open items filed by a fielded engine wear its spellings,
154-// closed items keep theirs forever, and members converge on their own schedules. So
155-// every reader here goes through one pass that maps every spelling ever written
156-// straight to today's — never through a literal comparison against one of them.
157:const LEGACY_STATUS = new Map([
158-  [BLOCKED, STATUS_BLOCKED],
159-  [READY, STATUS_READY],
160-  [EXECUTING, STATUS_RUNNING_EXECUTOR],
161-  [AGENT, STATUS_RUNNING_AGENT],
162-  [TASK_DONE, STATUS_DONE], [OUTCOME_DONE, STATUS_DONE],
163-  [TASK_OBSOLETE, STATUS_REJECTED], [OUTCOME_OBSOLETE, STATUS_REJECTED],
164-]);
165-
166-const LEGACY_PARK_RE = /^task:needs-human-(.+)$/;
