182-// item mid-flip — wearing a legacy spelling beside its canonical one — reads as the
183-// ONE status it is, and only genuinely conflicting labels read as more than one
184-// (the dashboard's `torn`).
185-export function statusesOn(issue) {
186-  const names = labelNames(issue);
187-  const out = new Set();
188-  const park = parkOf(names);
189-  if (park) out.add(park);
190-  for (const n of names) {
191-    if (STATUS_LABELS.includes(n) && !n.startsWith(PARK_PREFIX)) out.add(n);
192:    else if (LEGACY_STATUS.has(n)) out.add(LEGACY_STATUS.get(n));
193-  }
194-  return [...out];
195-}
