229-// A kind word (from a worker's own triage marker, or a call site) to its label.
230-/ Anything unrecognised is a `failure`: a worker that misspells its class has a
231-// bug, which is exactly what that lane means.
232-export const triageLabelFor = (kind) =>
233-  (TRIAGE_LABELS.includes(triage(kind)) ? triage(kind) : NEEDS_HUMAN_FAILURE);
